mapper.select:
SELECT hostname name,ip
FROM traffic_abnormal_machine
WHERE nmsServer_Id = #{nmsServiceId};

SELECT REDIRECT_NUM ,MONITOR_NUM,REPLACE_NUM
FROM pxy_total_report

    WHERE REPORT_TIME >= #{start}
    AND REPORT_TIME < #{end}


SELECT  #{start} time,if((sum(b.OUTOCTETS+b.INOCTETS) - a.count )>0  ,(sum(b.OUTOCTETS+b.INOCTETS) - a.count)/300 ,sum(b.OUTOCTETS+b.INOCTETS)/300) as count
FROM (
      SELECT  (sum(INOCTETS)+sum(OUTOCTETS)) count
      FROM traffic_netflow_port_info
      WHERE RECV_TIME >= #{before}
      AND RECV_TIME < #{start}) a,
      traffic_netflow_port_info b
WHERE b.RECV_TIME >= #{start}
AND b.RECV_TIME <  #{end}

SELECT RECV_TIME
FROM traffic_netflow_port_info

  WHERE RECV_TIME < #{end}
  ORDER BY RECV_TIME desc
  LIMIT 1;
